"""Centralized native Qt styling for the GDS Deep Current system."""
COLORS = {"navy":"#1E3A5F","dark":"#0F2440","darker":"#0A1628","light":"#2A4D7A","seafoam":"#2DD4BF","accent":"#14B8A6","danger":"#EF4444","workspace":"#E7EAEC","surface":"#FFFFFF","border":"#D8E0E8","muted":"#65758A","text":"#17263A"}
# Assets provide WOFF2 webfonts only; native Qt safely uses these system fallbacks.
FONT_BODY="Segoe UI"; FONT_DISPLAY="Segoe UI Semibold"; FONT_DATA="Cascadia Mono"
STYLESHEET=f"""
QMainWindow {{ background:{COLORS['workspace']};color:{COLORS['text']};font-family:'{FONT_BODY}';font-size:13px; }}
QWidget {{ color:{COLORS['text']};font-family:'{FONT_BODY}';font-size:13px; background:transparent; }}
#appRoot,#configurePage {{ background:{COLORS['workspace']}; }}
#sidebar {{ background:{COLORS['darker']};border:0; }} #brand {{ color:#FFF;font-family:'{FONT_DISPLAY}';font-size:18px;font-weight:700;letter-spacing:1px; }} #productSubtle,#fieldLabel {{ color:#9BAABA;font-size:11px;letter-spacing:.7px; }}
#header {{ background:#FFF;border-bottom:1px solid {COLORS['border']}; }} #brandDark {{ color:{COLORS['navy']};font-family:'{FONT_DISPLAY}';font-size:18px;font-weight:700;letter-spacing:1px; }} #productSubtleDark,#fieldLabelDark {{ color:{COLORS['muted']};font-size:10px;letter-spacing:1px; }} #sectionTitle {{ color:{COLORS['navy']};font-family:'{FONT_DISPLAY}';font-size:16px;font-weight:700;letter-spacing:.3px; }} #sectionSubtitle {{ color:{COLORS['muted']};font-size:12px; }} #cardTitle {{ color:{COLORS['dark']};font-family:'{FONT_DISPLAY}';font-size:14px;font-weight:700;letter-spacing:.7px; }}
QFrame#card {{ background:{COLORS['surface']};border:1px solid {COLORS['border']};border-radius:16px; }} QFrame#healthTile {{ background:#FCFDFE;border:1px solid #E6EBF0;border-radius:10px; }} QLabel#metric {{ color:{COLORS['dark']};font-family:'{FONT_DATA}';font-size:14px;font-weight:600; }}
QPushButton {{ min-height:38px;background:{COLORS['navy']};color:#FFF;border:0;border-radius:8px;padding:0 14px;font-weight:600; }} QPushButton:hover {{ background:{COLORS['light']}; }} QPushButton:pressed {{ background:{COLORS['dark']}; }} QPushButton:disabled {{ background:#D8E0E8;color:#7A899B; }} QPushButton#secondaryButton {{ background:#FFF;color:{COLORS['navy']};border:1px solid #C7D2DD; }} QPushButton#secondaryButton:checked {{ background:#E6F8F4;color:#087D70;border:1px solid #2DD4BF; }}
QPushButton#nav {{ background:transparent;color:#C5D1DE;text-align:left;padding:0 14px;border-radius:8px;min-height:38px;font-weight:600; }} QPushButton#nav:hover {{ background:#173352;color:#FFF; }} QPushButton#nav:checked {{ background:{COLORS['light']};color:#FFF; }} QPushButton#nav:disabled {{ background:transparent;color:#708196; }}
QComboBox {{ min-height:38px;padding:0 28px 0 10px;background:#FFF;border:1px solid #C7D2DD;border-radius:8px;color:{COLORS['text']}; }} QComboBox:hover,QComboBox:focus {{ border:1px solid {COLORS['navy']}; }} QComboBox::drop-down {{ border:0;width:24px; }} QComboBox QAbstractItemView {{ background:#FFF;border:1px solid {COLORS['border']};selection-background-color:#E8EEF5;selection-color:{COLORS['dark']}; }}
QScrollArea {{ border:0;background:transparent; }} QScrollBar:vertical {{ width:8px;background:transparent;margin:4px; }} QScrollBar::handle:vertical {{ background:#AAB7C5;border-radius:4px;min-height:24px; }} QScrollBar::add-line:vertical,QScrollBar::sub-line:vertical {{ height:0; }}
QLineEdit#identityInput,QLineEdit#vdrDateInput {{ min-height:36px;padding:0 10px;background:#FFF;border:1px solid #C7D2DD;border-radius:8px;color:{COLORS['text']}; }} QLineEdit#identityInput:focus {{ border:1px solid {COLORS['navy']}; }}
#fieldError {{ color:#B42318;font-size:11px;font-weight:600; }} #identityStatus {{ color:#087D70;font-size:11px;font-weight:700; }} #identityStatus[attention="true"] {{ color:#9A5B00; }}
QLabel[plausibility="warning"] {{ color:#8A5300; }} QLabel[plausibility="invalid"] {{ color:#B42318; }}
QLabel[badgeTone] {{ border-radius:9px; padding:3px 9px; font-size:11px; font-weight:700; }} QLabel[badgeTone="success"] {{ color:#087D70; background:#E6F8F4; }} QLabel[badgeTone="warning"] {{ color:#8A5300; background:#FFF4DC; }} QLabel[badgeTone="error"] {{ color:#B42318; background:#FDECEC; }} QLabel[badgeTone="neutral"] {{ color:#59697B; background:#EEF2F6; }}
#linkDetail {{ color:#59697B;background:#F6F8FA;border:1px solid #E6EBF0;border-radius:8px;padding:8px 10px;font-size:11px; }} #linkDetail[tone="success"] {{ border-left:3px solid #2DD4BF; }} #linkDetail[tone="warning"] {{ border-left:3px solid #D9A441; }} #linkDetail[tone="error"] {{ border-left:3px solid #B42318; }}
#connectionMessage {{ color:#7A2E0E;background:#FFF4ED;border:1px solid #F5C9A9;border-radius:8px;padding:8px 10px;font-size:12px; }}
#statusLive {{ color:#087D70;background:#E6F8F4;border-radius:10px;padding:4px 10px;font-size:11px;font-weight:700; }} #statusNeutral {{ color:#59697B;background:#EEF2F6;border-radius:10px;padding:4px 10px;font-size:11px;font-weight:700; }} #technicalValue,#summaryValue {{ color:{COLORS['dark']};font-family:'{FONT_DATA}';font-size:14px;font-weight:600; }} #diagnosticValue {{ color:{COLORS['navy']};font-family:'{FONT_DATA}';font-size:15px;font-weight:700; }} #operationalValue {{ color:{COLORS['navy']};font-family:'{FONT_DATA}';font-size:20px;font-weight:700; }} #summary {{ background:#FFF;border:1px solid {COLORS['border']};border-radius:14px; }} #topTabs {{ background:#FFF;border-bottom:1px solid {COLORS['border']};min-height:48px; }} QPushButton#moduleTab {{ background:transparent;color:{COLORS['muted']};min-height:44px;border-radius:0;padding:0 16px; }} QPushButton#moduleTab:checked {{ color:{COLORS['navy']};border-bottom:3px solid {COLORS['navy']}; }} QPushButton#moduleTab:disabled {{ background:transparent;color:#7D8A9A; }}
"""
